   114			const batch = idList.slice(i, i + 50);
   115			const turn = arxivGate.then(async () => {
   116				const url = `https://export.arxiv.org/api/query?id_list=${batch.join(",")}&max_results=${batch.length}`;
   117				for (let attempt = 0; attempt < 3; attempt++) {
