   122				return null;
   123			});
   124			arxivGate = turn.then(() => sleep(3100));
   125			const xml = await turn;
   126			if (xml === null) { for (const id of batch) titles.set(id, undefined); continue; }
   127			for (const entry of xml.split("<entry>").slice(1)) {
   128				const id = entry.match(/<id>https?:\/\/arxiv\.org\/abs\/([^<]+?)(v\d+)?<\/id>/)?.[1];
   129				const title = entry.match(/<title>([\s\S]*?)<\/title>/)?.[1].replace(/\s+/g, " ").trim();
   130				const author = entry.match(/<author>\s*<name>([^<]+)<\/name>/)?.[1].trim().split(/\s+/).pop();
